// A dependency compiled beside an entry that passes --unchecked-indexing and
// --wrapping (`../../args`). Neither flag reaches it: its `+` keeps `nsw` and
// its index keeps the bounds check, so `at(xs, 5)` panics as it would in any
// other program.
export const sum = (a: i32, b: i32): i32 => a + b;

export const at = (xs: i32[], i: i32): i32 => xs[i];
